insert into public.wines (bottle, country, region, drinking_window, food_pairing_notes, meal_suggestion, style, grapes, notes, location, vintage, quantity, rating, price, peak_year, status, from_cellar, coravin, consumed_date, coravin_date, technical_sheet_url, bottle_image_url, id, cellar_id) values
('Gran Enemigo – Gualtallary', 'Argentina', 'Uco Valley (Mendoza)', '2023–2035', 'Structured, mineral Malbec with Cabernet Franc notes; great with grilled red meats and Argentine dishes.', 'Argentine asado (steak, chorizo)', 'Red', 'Cabernet Franc & Malbec', '', 'Wine Fridge A - L1', 2019, 1, NULL, NULL, '2029', 'in_cellar', true, false, NULL, NULL, 'https://enemigowines.com/wp-content/uploads/2023/08/Gran-Enemigo-Gualtallary-2019.pdf', 'https://www.bswliquor.com/cdn/shop/files/el-enemigo-gran-enemigo-gualtallary-2016_bbe7e547-42b1-409a-a046-324afdb010d9.png?v=1753126784&width=2600', '1', '1'),
('Lorenzo Lo Sagrado Cabernet Franc', 'Argentina', 'Agrelo, Luján de Cuyo (Mendoza)', '2024–2032', 'Bright red‑fruit Cabernet Franc; suits herb‑roasted poultry, pork or lamb, and peppery dishes.', 'Roast duck with plum sauce', 'Red', 'Cabernet Franc', '', 'Wine fridge A - L3', 2019, 1, NULL, NULL, '2027', 'in_cellar', true, false, NULL, NULL, NULL, 'https://lorenzowines.com.ar/wp-content/uploads/2021/05/BANNERS-web-19.png', '2', '1'),
('Abbazia di Novacella Alto Adige Valle Isarco DOC', 'Italy', 'Alto Adige (Valle Isarco)', '2020–2028', 'Crisp, with notes of green apple, citrus, white pepper, and herbs. Excellent with asparagus, artichokes, grilled fish, shellfish, or veal in light sauces. Cuts through cream-based dishes and mildly spicy Asian cuisine.', 'Pan-seared scallops with a garlic-lemon beurre blanc sauce, served with a side of creamy risotto and sautéed spinach.', 'White', 'Grüner Veltliner', '', 'Wine Heaven', 2018, 1, NULL, NULL, '2023', 'consumed', true, false, '2026-05-19', '2026-01-15', NULL, 'https://images.vivino.com/thumbs/5SLjVc6QTXq8rtBkA-9FiA_pb_x600.png', '3', '1'),
('New Chapter Grüner Veltliner', 'Austria', 'Niederösterreich (Lenzmark)', '2022–2026', 'Crisp Grüner Veltliner; complements schnitzel and spicy Asian cuisine.', 'Wiener Schnitzel', 'White', 'Grüner Veltliner', 'Shared with wife on friday night dinner with chicken schnitzel preceeded by a small portion of pacheri caccio e pepe. Crisp, honeydew and green appple. Nose sweet.', 'Wine Heaven', 2021, 1, NULL, NULL, '2023', 'consumed', true, false, '2025-09-13', NULL, NULL, 'https://www.vinvm.co.uk/image/cache/catalog/new-chapter-gruner-veltliner-popup.jpg?v1636446885', '4', '1'),
('Santa Rita "Casa Real" Cabernet Sauvignon Reserva Especial', 'Chile', 'Maipo Valley', '2024–2038', 'Classic Chilean Cabernet with cassis, cedar and mint; needs grilled steaks, lamb or aged cheeses.', 'Ribeye steak with rosemary potatoes', 'Red', 'Cabernet Sauvignon', '', 'Wine fridge A - L1', 2018, 1, NULL, NULL, '2030', 'in_cellar', true, false, NULL, NULL, NULL, 'https://www.santarita.com/wp-content/uploads/2022/11/casa-real-2018.jpg', '5', '1'),
('Garage Wine Co. "Truquilemu Vineyard" Carignan Field Blend Lot 97', 'Chile', 'Maule Valley', '2024–2034', 'Concentrated Carignan blend with dark fruit and spice; pairs with game, barbecue and hearty stews.', 'Slow‑cooked venison stew', 'Red', 'Carignan', '', 'Wine fridge A - L2', 2019, 1, NULL, NULL, '2028', 'in_cellar', true, false, NULL, NULL, 'https://garagewine.company/wp-content/uploads/2022/06/Vigno-2019-en.pdf', 'https://assets.wine.com/winecom/image/upload/w_600,h_600,dpr_2.0,c_fit,q_auto:good,fl_progressive/ys00r4ogl7opoxi8k8zj.jpg', '6', '1'),
('Domaine Huet – Clos du Bourg Moelleux', 'France', 'Vouvray (Loire)', '2022–2040+', 'Sweet Chenin Blanc with honeyed stone fruit; pairs with foie‑gras, blue cheese or spicy Asian food.', 'Foie gras terrine', 'Sweet', 'Chenin Blanc', '', 'Wine fridge A - L1', 2018, 1, NULL, NULL, '2030', 'in_cellar', true, false, NULL, NULL, NULL, 'https://rogcowines.com/wp-content/uploads/2022/11/14255098-1_1611841237_clipped_rev_1-800x800.png', '7', '1'),
('Corton "Le Clos du Roi" Grand Cru (Domaine d''Ardhuy)', 'France', 'Burgundy (Corton)', '2025–2040', 'Grand Cru Pinot Noir; intense cherry and earth; needs time; pairs with duck, beef or mushrooms.', 'Beef Bourguignon', 'Red', 'Pinot Noir', '', 'Wine fridge A - L1', 2018, 1, NULL, NULL, '2030', 'in_cellar', true, false, NULL, NULL, NULL, 'https://www.oakcava.gr/wp-content/uploads/2022/07/DARDHUY-CORTON-CLOS-DU-ROI.png', '8', '1'),
('Clos de Saint Yves (Domaine des Baumard)', 'France', 'Savennières (Loire)', '2023–2030', 'Dry Chenin Blanc; quince, honey and chalky minerality; works with shellfish, poultry and creamy sauces.', 'Pan‑seared sea bass with beurre blanc', 'White', 'Chenin Blanc', '', 'Wine Heaven', 2019, 1, NULL, NULL, '2026', 'consumed', true, false, '2026-09-02', NULL, NULL, 'https://buzzwines.com/cdn/shop/files/BaumardCSYNV_ccfab5dd-e766-4490-b31e-d8a89bd73185_2048x.jpg?v=1683589881', '9', '1'),
('E. Guigal – Crozes‑Hermitage', 'France', 'Northern Rhône', '2023–2030', 'Syrah showing black‑pepper and blackberry; pairs with lamb, grilled meats or cassoulet.', 'Herb‑crusted rack of lamb', 'Red', 'Syrah', 'Amazing structured tannin. Loved the balance. Had it with korean marinated short ribs and marinated pork.', 'Wine Heaven', 2019, 1, NULL, NULL, '2026', 'consumed', true, false, '2026-08-29', NULL, 'https://s3-ap-northeast-1.amazonaws.com/orchestracms/eosportal/pdf/tasting-notes/guigal-crozes-hermitage-rouge-2019.pdf', 'https://nlliquor.com/wp-content/uploads/10838-1-640x640.jpg', '10', '1'),
('Château La Nerthe "Clos de Beauvenir"', 'France', 'Châteauneuf‑du‑Pape', '2024–2032', 'White Rhône blend (Roussanne‑dominant); honeyed stone fruit and floral; suits poultry, rich fish or truffle dishes.', 'Roast chicken with truffle butter', 'White', 'Roussanne (dominant)', '', 'Wine Fridge A - L4', 2021, 1, NULL, NULL, '2026', 'in_cellar', true, false, NULL, NULL, NULL, 'https://bbr.co.jp/cdn/shop/files/20218028974-2021-Chateauneuf-du-Pape-Blanc-Clos-de-Beauvenir_Chateau-La-Nerthe-Rhone_01.jpg?v=1722241619', '11', '1'),
('Famille Perrin Château de Beaucastel Roussanne Vieilles Vignes', 'France', 'Châteauneuf‑du‑Pape', '2024–2034', 'Complex, oak‑fermented Roussanne; pairs with lobster, scallops or creamy pasta.', 'Butter‑poached lobster', 'White', 'Roussanne', '', 'Wine fridge A - L1', 2021, 1, NULL, NULL, '2028', 'in_cellar', true, false, NULL, NULL, 'https://m.familleperrin.com/1I1MIE/get/print', 'https://static.millesima.com/s3/attachements/h1000px/F486_2021NM_c.png', '12', '1'),
('Joseph Mellot "Cuvée Pierre‑Étienne" Sancerre', 'France', 'Sancerre (Loire)', '2020–2030', 'Mature Sancerre with citrus and flinty notes; ideal with goat cheese, shellfish and light poultry.', 'Goat‑cheese and herb salad', 'White', 'Sauvignon Blanc', '', 'Wine Heaven', 2017, 1, NULL, NULL, '2025', 'consumed', true, false, '2026-08-30', NULL, 'https://www.josephmellot.com/wp-content/uploads/2018/04/JM-SANCERRE-BLANC-CUVEE-PIERRE-ETIENNE-2017-En.pdf', 'https://josephmellot.com/wp-content/uploads/2022/11/pierre-etienne-sancerre.jpg', '13', '1'),
('Château d''Agassac', 'France', 'Bordeaux (Haut‑Médoc)', '2015–2030', 'Cabernet‑Merlot blend; great with steak, duck confit and aged cheeses.', 'Duck confit with potatoes', 'Red', 'Cabernet Sauvignon & Merlot', 'On August 8, 2025, at Rodrigo’s house in Sao Paulo. Its depth met the richness of a beautifully cooked bacalhau in olive oil with onions and broccoli, in great harmony. A memorable pairing, shared in good company. It is incredible how age improve the texture of the wine and develops leather and light tobacco notes.', 'Wine Heaven', 2012, 1, 4, NULL, '2023', 'consumed', true, false, '2025-08-08', NULL, 'https://www.agassac.com/fiche/pdf/millesime_194.pdf', 'https://geisels-weingalerie.de/media/49/41/03/1690809627/450490-removebg-preview.png', '14', '1'),
('Château Princé Chenin Sec "Les Ardoisières"', 'France', 'Anjou (Loire)', '2022–2032', 'Dry Chenin Blanc; pairs with seafood, poultry and creamy sauces.', 'Roast chicken with lemon & thyme', 'White', 'Chenin Blanc', '', 'Wine Heaven', 2019, 1, NULL, NULL, '2026', 'consumed', true, false, '2026-09-08', NULL, 'https://www.chateauprince.fr/wp-content/uploads/2025/02/Les-Ardoisieres-2020-Chateau-Prince.pdf', 'https://www.npwines.com/cdn/shop/files/2025-LCBORetailReleases_7.png?v=1736355051', '15', '1'),
('Bernard Lonclas Blanc de Blancs Extra Brut Vintage', 'France', 'Champagne', '2020–2030', 'The Bernard Lonclas Blanc de Blancs Extra Brut Vintage 2015 showcases a crisp profile with vibrant citrus notes and a hint of brioche. This elegant Champagne pairs exceptionally well with seafood dishes, particularly shellfish and sushi, enhancing the freshness of the ingredients. For optimal enjoyment, decant for 30 minutes to allow the flavors to open up. Critic score: WS 96.', 'Pan‑seared scallops with lemon butter or seafood risotto', 'Sparkling', 'Chardonnay', '', 'Wine Heaven', 2015, 1, NULL, NULL, '2025', 'consumed', true, false, '2026-08-30', NULL, 'https://www.champagne-lonclas.com/fr/vintage.php', 'https://aem.lcbo.com/content/dam/lcbo/products/0/4/4/9/044901.jpg.thumb.1280.1280.jpg', '16', '1'),
('Gaston Chiquet Rosé Premier Cru Brut', 'France', 'Champagne (Dizy)', '2024–2028', 'Rosé Champagne with red‑fruit notes; great with charcuterie, salmon and berry desserts.', 'Smoked salmon blinis', 'Sparkling', 'Pinot Noir, Chardonnay, Pinot Meunier', 'amazing', 'Wine Heaven', 2023, 1, NULL, NULL, '2025', 'consumed', true, false, '2026-08-30', NULL, NULL, 'https://aem.lcbo.com/content/dam/lcbo/products/0/4/4/4/044471.jpg.thumb.1280.1280.jpg', '17', '1'),
('Selbach‑Oster Graacher Domprobst Riesling Spätlese', 'Germany', 'Mosel', '2024–2045', 'Sweet but balanced Riesling; great with spicy Asian, pork dishes or fruity desserts.', 'Thai red curry with pork', 'Sweet', 'Riesling', 'Gorgeous green apple nose. Fresh and light. Loved it.', 'Wine Heaven', 2021, 1, NULL, NULL, '2032', 'consumed', true, false, '2025-10-26', NULL, NULL, 'https://aem.lcbo.com/content/dam/lcbo/products/5/3/2/7/532721.jpg.thumb.1280.1280.jpg', '18', '1'),
('Lungarotti "Rubesco Vigna Monticchio" (Torgiano Rosso Riserva)', 'Italy', 'Umbria', '2020–2035', 'Sangiovese/Canaiolo blend with earthy cherry and leather; pairs with roast pork, game or aged Pecorino.', 'Osso buco with saffron risotto', 'Red', 'Sangiovese & Canaiolo', '', 'Wine fridge A - L3', 2015, 1, NULL, NULL, '2028', 'in_cellar', true, false, NULL, NULL, NULL, 'https://www.wonderumbria.com/images/thumbs/phpThumb.php?q=80&w=740&h=740&zc=C&src=/images/g_20230704102130.jpg', '19', '1'),
('Lungarotti Montefalco Sagrantino DOCG', 'Italy', 'Umbria', '2027–2047', 'Powerful, tannic Sagrantino; traditionally paired with lamb and Umbrian dishes.', 'Braised lamb shank with mushrooms', 'Red', 'Sagrantino', '', 'Wine fridge A - L0', 2017, 1, NULL, NULL, '2032', 'in_cellar', true, false, NULL, NULL, NULL, 'https://landofwines.com/wp-content/uploads/2021/10/sagrantino.jpg', '20', '1'),
('Castello Banfi Poggio all''Oro Brunello di Montalcino Riserva', 'Italy', 'Tuscany (Brunello)', '2026–2046', 'The Castello Banfi Poggio all''Oro Brunello di Montalcino Riserva 2016 is a powerful Sangiovese that showcases rich cherry and plum flavors, complemented by earthy undertones and firm tannins. Ideal pairings include grilled ribeye steak or roasted game, alongside rich pasta dishes like pappardelle with wild boar ragu. Decant for at least 1 hour to enhance its complexity. Critic initials: RP 95.', 'Bistecca alla Fiorentina', 'Red', 'Sangiovese', '', 'Wine fridge A - L0', 2016, 1, NULL, NULL, '2032', 'in_cellar', true, false, NULL, NULL, 'https://www.datocms-assets.com/76721/1701177094-pao2016_eng.pdf', 'https://aem.lcbo.com/content/dam/lcbo/products/4/4/3/2/443267.jpg.thumb.1280.1280.jpg', '21', '1'),
('Volpaia Coltassala', 'Italy', 'Tuscany (Chianti Classico)', '2025–2040', 'Volpaia Coltassala 2019 is a refined Gran Selezione Chianti that showcases the vibrant acidity and ripe red fruit profile typical of Sangiovese, complemented by the floral notes of Mammolo. This wine pairs beautifully with hearty Tuscan dishes, such as a rich Tuscan ragù or a succulent roast lamb with rosemary. For optimal enjoyment, decant for 1-2 hours to allow the flavors to open up. Critic: RP 93.', 'Pappardelle al ragù di cinghiale', 'Red', 'Sangiovese & Mammolo', '', 'Wine fridge A - L0', 2019, 1, NULL, NULL, '2032', 'in_cellar', true, false, NULL, NULL, NULL, 'https://volpaia.com/wp-content/uploads/2020/05/Coltassala.png', '22', '1'),
('Triacca San Domenico Sforzato di Valtellina', 'Italy', 'Lombardy (Valtellina)', '2025–2038', 'The Triacca San Domenico Sforzato di Valtellina is a rich, dried-grape Nebbiolo that displays deep flavors and a full-bodied profile. It pairs beautifully with braised meats like osso buco and hearty aged cheeses such as Parmigiano-Reggiano. For optimal enjoyment, decant for at least 1 hour to allow the complex aromas to develop. Critics have noted this vintage with a score of RP 96.', 'Braised beef cheeks with polenta', 'Red', 'Nebbiolo (Chiavennasca)', '', 'Wine Heaven', 2017, 1, NULL, NULL, '2030', 'consumed', true, true, '2026-09-02', '2026-01-10', NULL, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSf3-FMGbpaHQQIj1Qy27U3ql1zfpGOV9rMjQ&s', '23', '1'),
('Casa Ferreirinha Castas Escondidas Douro', 'Portugal', 'Douro', '2024–2034', 'The Casa Ferreirinha Castas Escondidas Douro 2019 is a rich, full-bodied red blend featuring Touriga Franca and Tinta Barroca, offering dark fruit flavors and a hint of spice. It pairs excellently with grilled beef, game meats, and hearty stews. For optimal enjoyment, decant for 1-2 hours to allow the wine to breathe and reveal its complexity. Critics have noted its quality, with a score of RP 94.', 'Grilled lamb chops with rosemary, served with garlic mashed potatoes and a red wine reduction sauce.', 'Red', 'Touriga Franca, Tinta Barroca & others', '', 'Wine fridge A - L2', 2019, 2, NULL, NULL, '2028', 'in_cellar', true, false, NULL, NULL, NULL, 'https://www.theoldbarracks.ie/cdn/shop/files/Screenshot2025-02-25at14.56.31.png?v=1740495461', '24', '1'),
('Casa Ferreirinha Quinta da Leda', 'Portugal', 'Douro', '2024–2034', 'Structured Touriga blend; dark fruit and chocolate; pairs with grilled beef, venison or stews.', 'Portuguese cozido', 'Red', 'Touriga Nacional, Tinta Roriz, Tinta Barroca, others', '', 'Wine fridge A - L2', 2018, 1, NULL, NULL, '2027', 'in_cellar', true, false, NULL, NULL, NULL, 'https://www.datocms-assets.com/33016/1634141398-quinta-da-leda-2018-75cl-packshot.jpg?auto=format&fit=max&w=1200', '25', '1'),
('Guarita da Chocapalha', 'Portugal', 'Lisbon region', '2022–2030', 'Alicante Bouschet from old vines; ripe plum and spice; pairs with roast pork and chouriço dishes.', 'Porco Preto (roast Iberian pork)', 'Red', 'Alicante Bouschet', '', 'Wine Heaven', 2016, 1, NULL, NULL, '2025', 'consumed', true, false, '2025-10-26', NULL, 'https://chocapalha.pt/wp-content/uploads/2019/04/Guarita-da-Chocapalha-Red-2015_FT_PT.pdf', 'https://thebeerman.ca/storage/2024/02/30886.jpg', '26', '1'),
('Ferreira Vintage Port', 'Portugal', 'Douro', '2030–2075', 'Fortified and powerful; matches blue cheeses, dark chocolate or dried fruits.', 'Stilton cheese & fig tart', 'Fortified', 'Touriga Nacional, Touriga Franca, Tinta Barroca, Tinta Roriz, others', '', 'Wine fridge A - L0', 2018, 1, NULL, NULL, '2045', 'in_cellar', true, false, NULL, NULL, 'https://www.datocms-assets.com/33016/1719027540-porto-ferreira-vintage-2018-en-v0-c-2023072811970739-cff9d65b.pdf', 'https://swaso.ca/cdn/shop/products/iffn_2b8Q1axnKwj4OtXuw_pb_x600_0c46299b-8561-4dc5-a171-8400f4d133c0.png?v=1668372330', '27', '1'),
('Quinta da Manoella Vinhas Velhas', 'Portugal', 'Douro', '2025–2035', 'Old‑vine Douro red; concentrated dark fruit and spice; pairs with game, grilled lamb or rich stews.', 'Wild boar ragù with tagliatelle', 'Red', 'Field blend (Touriga Nacional, etc.)', '', 'Wine fridge A - L2', 2019, 1, NULL, NULL, '2029', 'in_cellar', true, false, NULL, NULL, NULL, 'https://cdn.shoplightspeed.com/shops/640383/files/65057975/image.jpg', '28', '1'),
('Torre Muga Rioja', 'Spain', 'Rioja', '2025–2040', 'Tempranillo blend; dark cherry, leather and vanilla; pairs with lamb, Ibérico ham or mushroom dishes.', 'Slow‑cooked lamb shoulder', 'Red', 'Tempranillo, Graciano, Mazuelo', '', 'Wine fridge A - L0', 2019, 1, NULL, NULL, '2032', 'in_cellar', true, false, NULL, NULL, 'https://www.bodegasmuga.com/wp-content/uploads/2022/02/muga-torremuga-2019-eng.pdf', 'https://assets.tastingbook.com/assets/full/b4bc086710cd1a28b39957781faaee78.jpg', '30', '1'),
('Arzuaga Reserva Especial', 'Spain', 'Ribera del Duero', '2027–2042', 'Elegant blend of Tempranillo and Cabernet Sauvignon, showcasing rich dark fruit flavors, balanced acidity, and subtle oak. This wine pairs beautifully with roast lamb, particularly when seasoned with rosemary and garlic, as well as with Ibérico pork, which complements its depth. For optimal enjoyment, decant for at least 1 hour to allow the wine to breathe. Critic score: RP 94.', 'Grilled ribeye steak with chimichurri sauce, served with roasted asparagus and garlic mashed potatoes.', 'Red', 'Tempranillo & Cabernet Sauvignon', '', 'Wine Fridge A - L0', 2019, 1, NULL, NULL, '2031', 'in_cellar', true, false, NULL, NULL, 'https://arzuaganavarro.com/images/ARZUAGA/Fichas-PDF/Reserva_especial/Reserva_Especial_19.pdf', 'https://cdn.8wines.com/media/catalog/product/cache/55604a2f1b80c53a58291908f0e5a9e4/a/r/arzuaga-reserva-especial-2019.png', '31', '1'),
('Pepe Mendoza Casa Agrícola El Veneno', 'Spain', 'Alicante', '2023–2030', 'Mediterranean Garnacha with ripe berry fruit and herbs; pairs with grilled meats, paella and tapas.', 'Paella Valenciana', 'Red', 'Monastrell', '', 'Wine Heaven', 2020, 1, NULL, NULL, '2026', 'consumed', true, false, '2026-09-02', NULL, 'https://casaagricola.es/wp-content/uploads/2023/09/EN_FT_CA_ElVeneno_2020.pdf', 'https://www.alliancewine.com/images/products/BOTTLE_4998.png?mode=pad&quality=90&height=842', '32', '1'),
('Plácet de Valtomelloso (white Rioja)', 'Spain', 'Rioja', '2023–2028', 'Elegant, oak‑fermented Viura; works with seafood, paella or grilled vegetables.', 'Seafood paella', 'White', 'Viura', '', 'Wine Heaven', 2021, 1, NULL, NULL, '2025', 'consumed', true, false, '2026-08-30', NULL, NULL, 'https://www.decantalo.com/jp/68408-product_img/placet-valtomelloso.jpg', '33', '1'),
('Vi de Vila Gratallops', 'Spain', 'Priorat (Catalonia)', '2025–2035', 'Grenache/Carignan blend; mineral and intense; pairs with lamb, grilled beef or Catalan dishes.', 'Grilled lamb chops', 'Red', 'Garnacha & Carignan', '', 'Wine fridge A -  L1', 2022, 1, NULL, NULL, '2028', 'in_cellar', true, false, NULL, NULL, NULL, 'https://www.saq.com/media/catalog/product/1/5/15262821-1_1732034884.png?optimize=high&fit=bounds&height=&width=&format=jpeg', '34', '1'),
('J. Lohr "Cuvée POM"', 'United States', 'California (Paso Robles)', '2023–2035', 'Bordeaux‑style blend (Merlot‑dominant); blackberry and mocha; pairs with prime rib or braised beef.', 'Spanish paella or a grilled ribeye with shallots', 'Red', 'Merlot, Cabernet Sauvignon, Cabernet Franc, Malbec', '', 'Wine Heaven', 2018, 1, NULL, NULL, '2025', 'consumed', true, true, '2026-08-30', '2026-01-21', 'https://assets.jlohr.com/v3/general_files/18-Cuvee-POM.pdf', 'https://www.reservebar.com/_next/image?url=https%3A%2F%2Fassets.liquidcommerce.co%2Fcatalog%2Fpartner%2Fimg%2F31c2485f-1201-4317-a83a-9dd35ce3edab.jpg&w=256&q=75', '35', '1'),
('Champagne Thiénot Cuvée Alain Thiénot', 'France', 'Champagne (Reims)', '2015–2035', 'The Champagne Thiénot Cuvée Alain Thiénot 2008 is an elegant vintage sparkling wine, characterized by its fine bubbles and balanced acidity. It pairs excellently with seafood dishes such as oysters and caviar, as well as light sushi and creamy soft cheeses like brie. For optimal enjoyment, decant for 30 minutes to allow the aromas to open up. Critic score: WS 93.', 'Oysters with mignonette sauce', 'Sparkling', 'Chardonnay, Pinot Noir, Pinot Meunier', 'Good acidity, long finish, lemon, citrus notes. Med alcohol.', 'Wine Heaven', 2008, 1, NULL, NULL, '2025', 'consumed', true, false, '2025-10-12', NULL, 'https://www.champagne-thienot.com/wp-content/uploads/2025/07/Fiche-Produit_CUVEE-ALAIN-THIENOT_2008_FR.pdf', 'https://aem.lcbo.com/content/dam/lcbo/products/0/3/0/9/030971.jpg.thumb.1280.1280.jpg', '36', '1'),
('Casa Geraldo Gran Reserva Colheita de Inverno Merlot', 'Brazil', 'Serra da Mantiqueira (Sul de Minas Gerais)', '2022–2030', 'This full-bodied Brazilian Merlot from Serra da Mantiqueira exhibits rich fruit flavors and velvety tannins, making it an excellent match for hearty dishes. Ideal pairings include roast beef with a red wine reduction, lamb shanks braised in herbs, or aged hard cheeses like Parmigiano-Reggiano. For optimal enjoyment, decant for at least 30 minutes to allow the wine to breathe.', 'Roast beef with herbs', 'Red', 'Merlot', '', 'Wine Heaven', 2019, 1, NULL, NULL, '2026', 'consumed', true, false, '2026-09-02', NULL, 'https://www.casageraldo.com.br/merlot-gran-reserva-750ml', 'https://www.vinhosevinhos.com/media/catalog/product/cache/f551083cd20de7ac8cf7d25adc91480d/c/a/casa-geraldo-gran-reserva-merlot.jpg', '37', '1'),
('Primeira Estrada Chardonnay', 'Brazil', 'Serra da Mantiqueira (Sul de Minas Gerais)', '2024–2028', 'Fresh Brazilian Chardonnay; pairs nicely with seafood, chicken, and creamy pasta dishes.', 'Grilled salmon with lemon butter', 'White', 'Chardonnay', '', 'Wine Heaven', 2024, 1, NULL, NULL, '2025', 'consumed', true, false, '2026-09-02', NULL, NULL, 'https://www.vinhosevinhos.com/media/catalog/product/cache/c8681c74f2ad6e00a87f988c056011ef/p/r/primeira-estrada-chardonnay.jpg', '38', '1'),
('Primeira Estrada Gran Reserva Syrah Colheita de Inverno', 'Brazil', 'Serra da Mantiqueira (Sul de Minas Gerais)', '2023–2032', 'Structured Syrah with dark fruit and spice; pairs well with barbecue, lamb, or feijoada.', 'Brazilian lamb ribs slow-cooked on charcoal', 'Red', 'Syrah', '', 'Wine fridge A - L4', 2021, 1, NULL, NULL, '2027', 'in_cellar', true, false, NULL, NULL, NULL, 'https://www.vinhosevinhos.com/media/catalog/product/cache/f551083cd20de7ac8cf7d25adc91480d/p/r/primeira-estrada-gran-reserva-syrah.jpg', '39', '1'),
('Domaine Labruyère Champ de Cour Moulin-à-Vent', 'France', 'Beaujolais (Moulin-à-Vent, Saône-et-Loire)', '2021–2035', 'Pairs well with game stews like civet de lièvre, lamb navarin, beef stews, coq au vin, or veal liver.', 'Coq au vin', 'Red', 'Gamay', 'Deep and structured Gamay with aromas of violet, licorice, and pepper; concentrated fruit, fine tannins, and long aging potential (15+ years).', 'Wine Fridge A - L4', 2018, 1, NULL, NULL, '2027', 'in_cellar', true, false, NULL, NULL, NULL, 'https://www.lecarredesvins.com/18599-large_default/domaine-labruyere-moulin-a-vent-champ-de-cour-2016.jpg', '40', '1'),
('The Farm Pinot Noir End of the Road Vineyard', 'Canada', 'Ontario (VQA Twenty Mile Bench, Niagara Peninsula)', '2023–2029', 'Elegant Pinot Noir with red cherry, cranberry, and subtle earthy notes; pairs well with roast poultry, mushroom risotto, duck, or grilled salmon.', 'Duck breast with cherry reduction', 'Red', 'Pinot Noir', '', 'Wine Heaven', 2021, 1, NULL, NULL, '2026', 'consumed', true, false, '2025-11-17', NULL, 'https://static1.squarespace.com/static/5cfe6c2a8dc2800001ee4011/t/666f90602afbb055e7bda3ac/1718587489262/2021_THE+FARM_EOTR_retail.pdf', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSTECAsU9jwXBMc7lHotRYEt52X9_n0SiuWkw&s', '41', '1'),
('San Felice Campogiovanni Brunello di Montalcino', 'Italy', 'Tuscany (Brunello)', '2019–2035', 'Structured Sangiovese Grosso with cherry, leather and tobacco notes; excels with bistecca, wild-boar ragù, osso buco, mushroom dishes and aged Pecorino.', 'Pappardelle al ragù di cinghiale', 'Red', 'Sangiovese', '', 'Wine Heaven', 2012, 1, NULL, NULL, '2027', 'consumed', true, false, '2026-09-02', NULL, 'https://admin.sanfelice.com/app/uploads/2023/04/SF-CampogiovanniBrunMontDocg-2015-IT.pdf?_gl=1*6552eb*_up*MQ..*_ga*MjA5OTc1ODk3OC4xNzU2OTk0OTA4*_ga_YJ8Q1ZCK2E*czE3NTY5OTQ5MDgkbzEkZzAkdDE3NTY5OTQ5MDgkajYwJGwwJGgw', 'https://cdn11.bigcommerce.com/s-oyi93ews/images/stencil/1280w/products/19330/15584/2025-01-16_14.24.41__53478.1737137892.png?c=2', '42', '1'),
('Luigi Baudana Baudana Barolo', 'Italy', 'Piedmont (Barolo)', '2027–2043', 'Classic Nebbiolo with cherry, rose, tar and firm tannins; pairs with long-cooked beef, lamb, game, truffle dishes, and aged Pecorino/Parmigiano.', 'Brasato al Barolo (accompanied by polenta cremosa)', 'Red', 'Nebbiolo', '', 'Wine Heaven', 2021, 1, NULL, NULL, '2034', 'consumed', true, false, '2026-04-15', NULL, 'https://www.baudana.it/wp-content/uploads/2025/02/FS-BOBA21-IT-.pdf', 'https://cache2.voyageursduvin.com/products/Luigi-Baudana-Barolo-Baudana-zoom.jpg', '43', '1'),
('Two Hands Bella''s Garden Shiraz', 'Australia', 'Barossa Valley', '2023–2034', 'The 2021 Two Hands Bella''s Garden Shiraz is a full-bodied Barossa Valley red, showcasing ripe blackberry and blueberry notes complemented by hints of pepper, licorice, and cocoa. This wine pairs exceptionally well with grilled lamb chops served with rosemary and garlic, as well as beef short ribs in a rich barbecue sauce. Decant for at least 30 minutes to enhance its complexity. Critic score: JS 95.', 'Grilled beef ribeye steak with a red wine reduction sauce, served with roasted garlic mashed potatoes and sautéed asparagus.', 'Red', 'Syrah', '', 'Wine fridge A - L3', 2021, 1, NULL, NULL, '2028', 'in_cellar', true, false, NULL, '2026-01-17', 'https://twohandswines.com/pages/bellas-garden', 'https://cache1.voyageursduvin.com/products/Two-Hands-Bellas-Garden-zoom.jpg', '44', '1'),
('Château Suduiraut', 'France', 'Sauternes', '2025-2040', 'This sweet wine typically exhibits rich flavors of honey, apricot, and citrus with balanced acidity. It pairs well with desserts, foie gras, and blue cheese.', 'Foie gras torchon with a fig compote and toasted brioche', 'Sweet', 'Sémillon, Sauvignon Blanc', '', 'Wine Fridge A - L6', 2014, 1, NULL, NULL, '2030', 'in_cellar', true, false, NULL, NULL, NULL, 'https://www.wineinvestment.com/assets/Uploads/Chateau_Suduiraut_-_Chateau_Suduiraut__ScaleMaxWidthWzQwMF0.png', '45', '1'),
('Pauly Helden 2023 Riesling - Alte Reben', 'Germany', 'Mosel', '2024-2030', 'This Riesling is likely to have bright acidity, floral notes, and stone fruit flavors, making it a great match for dishes that complement its freshness and minerality.', 'Grilled lemon-herb chicken with a side of asparagus and a light garlic butter sauce.', 'White', 'Riesling', '', 'Wine Heaven', 2023, 1, NULL, NULL, '2026', 'consumed', true, false, '2026-09-07', NULL, NULL, 'https://aem.lcbo.com/content/dam/lcbo/products/0/4/6/3/046386.jpg.thumb.1280.1280.jpg', '1764117328696', '1'),
('Chateau Clerc Milon 2020', 'France', 'Bordeaux Pauillac', '2025-2035', 'This wine typically exhibits rich dark fruit flavors, balanced acidity, and firm tannins, making it a great match for hearty dishes. Pair with grilled meats or rich sauces to complement its structure.', 'Braised beef short ribs with a red wine reduction, served with creamy mashed potatoes and sautéed green beans.', 'Red', 'Cabernet Sauvignon, Merlot, Cabernet Franc, Petit Verdot', '', 'Wine Fridge A - L1', 2020, 1, NULL, NULL, '2029', 'in_cellar', true, false, NULL, NULL, NULL, 'https://www.willowpark.net/cdn/shop/files/ChateauClercMilon.png?v=1734133509', '1764117502289', '1'),
('The Standish Wine Company The Schubert Theorem 2022', 'Australia', 'Barossa Valley', '2024-2032', 'This wine likely has rich fruit flavors and moderate tannins, making it suitable for pairing with hearty dishes. Ideal pairings include grilled meats or rich pasta dishes.', 'Grilled lamb chops with rosemary, served with a side of creamy polenta and roasted seasonal vegetables.', 'Red', 'Shiraz', '', 'Wine Fridge A - L3', 2022, 1, NULL, NULL, '2028', 'in_cellar', true, false, NULL, NULL, NULL, 'https://aem.lcbo.com/content/dam/lcbo/products/0/2/2/5/022535.jpg.thumb.1280.1280.jpg', '1764117575388', '1'),
('Stratus Cabernet Sauvignon 2019', 'Canada', 'Niagara-on-the-Lake', '2023-2030', 'This Cabernet Sauvignon likely has rich tannins and dark fruit flavors, making it a great match for hearty dishes. Ideal pairings include grilled meats or rich sauces.', 'Grilled ribeye steak with a red wine reduction sauce, served with roasted garlic mashed potatoes and sautéed green beans.', 'Red', 'Cabernet Sauvignon', '', 'Wine Heaven', 2019, 1, NULL, NULL, '2025', 'consumed', true, false, '2026-08-30', NULL, NULL, 'https://stratuswines.com/cdn/shop/files/2019-Stratus-CabernetSauvignon_1.png?v=1686842535', '1764117626016', '1'),
('Chateau La Tour Blanche 2016', 'France', 'Sauternes', '2023-2040', 'This Sauternes is rich and sweet with notes of honey, apricot, and citrus, making it a perfect match for desserts, foie gras, or blue cheese.', 'Seared foie gras with a fig compote and toasted brioche.', 'Sweet', 'Sémillon, Sauvignon Blanc', '', 'Wine Fridge A - L6', 2016, 1, NULL, NULL, '2028', 'in_cellar', true, false, NULL, NULL, NULL, 'https://aem.lcbo.com/content/dam/lcbo/products/0/3/7/4/037437.jpg.thumb.1280.1280.jpg', '1764117687338', '1'),
('Clos du Lican', 'Chile', 'Apalta', '2025-2035', '"I''ve never before smelled a wine like this. The captivating aromas are amazing, with lavender, sage, dried potpourri, blackberries, tar, pepper and black licorice. Full-bodied with super tannins that fan out and caress the palate. It''s ethereal and endless. A pure syrah from the owners of Clos Apalta, from unique mountain vineyards. Try to give this four or five years of bottle age. Best after 2028. Score - 100. (jamessuckling.com, Feb. 11, 2024)"', 'Braised beef cheeks with a red wine reduction, served alongside creamy polenta and sautéed seasonal greens.', 'Red', 'Syrah', '', 'Wine fridge A - L3', 2021, 1, NULL, NULL, '2028', 'in_cellar', true, false, NULL, NULL, 'https://www.closdulican.com/wp-content/uploads/2025/01/ClosduLican_FT_2021_EN.pdf', 'https://aem.lcbo.com/content/dam/lcbo/products/0/4/7/7/047724.jpg.thumb.1280.1280.jpg', '1770385391795', '1'),
('Michel Guignier Morgon Canon', 'France', 'Morgon', '2024-2032', 'The 2023 Michel Guignier Morgon Canon showcases bright acidity, soft tannins, and vibrant notes of cherry and raspberry. This profile makes it an excellent match for earthy dishes or light meats, such as roasted chicken with herbs and a side of sautéed mushrooms. Decant for 30 minutes to enhance its aromatic complexity. Critic score: RP 92.', 'Roasted herb-marinated chicken thighs, served with garlic mashed potatoes and roasted seasonal vegetables.', 'Red', 'Gamay', '', 'Wine Fridge A - L3', 2023, 1, NULL, NULL, '2028', 'in_cellar', true, false, NULL, NULL, NULL, 'https://aem.lcbo.com/content/dam/lcbo/products/0/5/1/1/051164.jpg.thumb.1280.1280.jpg', '1779157110325', '1'),
('Luigi Baudana Barolo', 'Italy', 'Piedmont', '2028-2040', 'This Barolo typically exhibits high acidity, firm tannins, and complex aromas of cherry, rose, and earthy notes, making it a great match for rich dishes.', 'Braised lamb shanks with rosemary and garlic, served with creamy polenta and sautéed seasonal vegetables.', 'Red', 'Nebbiolo', '', 'Wine Fridge A - L4', 2021, 1, NULL, NULL, '2035', 'in_cellar', true, false, NULL, NULL, NULL, 'https://zyn.ca/cdn/shop/files/Luigi-Baudana-Barolo-Cerretta-2021_1200x.jpg?v=1778594528', '1788389989910', '1'),
('Westcott Vineyards Estate Chardonnay 2024', 'Canada', 'Niagara Peninsula', '2025-2030', 'This Chardonnay is likely to have bright acidity and a creamy texture, making it a great match for dishes with rich flavors. Pair it with seafood, poultry, or creamy pasta dishes.', 'Grilled lemon herb chicken with a creamy garlic sauce, served with roasted asparagus and a side of wild rice.', 'White', 'Chardonnay', '', 'Wine Heaven', 2024, 1, NULL, NULL, '2026', 'consumed', true, false, '2026-09-05', NULL, NULL, NULL, '1788390393560', '1'),
